action.command:
python3 -c 'import json,hashlib,os
from pathlib import Path
b=Path("docs/research/poc/pair")
for name in ["constant-1-separate--constant-2-separate.json","constant-1-normal--constant-2-normal.json"]:
 d=json.loads((b/name).read_text()); print(name,"inputs",d["inputs"],"loader",d["loader_provenance"])
 for r in d["resources"]:
  if r.get("type") in ["BDHb","BDPW","DFDS","RTSG","VCTP","DTHP","LVSR"]: print(json.dumps(r))
d=json.loads((b/"candidates-0105.json").read_text())
for a in d["bdhb_alignments"]:
 if "constant" in str(a): print("ALIGN",json.dumps(a))
print("ENV",os.environ.get("LABVIEW_ENVIRONMENT"))
print("POC FILES",[str(p) for p in Path("docs/research/poc").glob("*")])
'

